arguments.new_string:
AUTORLBENCH_RESULTS=${AUTORLBENCH_RESULTS:-$PWD}
LOG_DIR=${LOG_DIR:-$AUTORLBENCH_RESULTS/experiment_logs}
mkdir -p "$LOG_DIR"
WANDB_MODE=${WANDB_MODE:-offline}
# Keep the key as one shell word even when it is a local placeholder.
WANDB_API_KEY=${WANDB_API_KEY:-local-offline}

# wandb.init(dir=...) always creates <dir>/wandb/offline-run-*. Point dir at
# the experiment log root so offline data lands at $LOG_DIR/wandb.
WANDB_ARGS=(
   --use-wandb
   --wandb-mode "$WANDB_MODE"
   --wandb-dir "$LOG_DIR"
   --wandb-project slime-retool
   --wandb-group qwen3-4B-retool-multi-turn
   --wandb-key "$WANDB_API_KEY"
)
